local _, addon = ...
addon.localeData.deDE.texts = {
    FIREBALL = { name = "Feuerball", ziel = { "Euch wird gleich warm, %s.", "*wirkt Feuerball auf %s.*", "%s, Eure Rüstung ist kein Ersatz für einen Feuerwiderstand." }, gruppe = { "Euch wird gleich warm.", "*konzentriert sich und entfesselt Feuerball.*", "Flammen sind ehrlicher als viele Verhandlungen.", "*entfacht eine Spirale bernsteinfarbener Funken.*", "Ich hoffe, Ihr mögt es knusprig.", "*zeichnet ein glühendes Siegel in die Luft.*", "Ein sauberer Feuerball braucht keinen zweiten Versuch.", "*verdichtet eine glühende Kugel zwischen den Handflächen.*", "Die Flamme folgt meiner Hand, nicht meiner Laune.", "*schließt die Finger um einen rotglühenden Feuerkern und schleudert ihn fort.*" } },
    FROSTBOLT = { name = "Frostblitz", ziel = { "Ein frostiger Gruß, %s.", "*wirkt Frostblitz auf %s.*", "%s, jeder Schritt wird Euch jetzt schwerer fallen." }, gruppe = { "Ein frostiger Gruß.", "*konzentriert sich und entfesselt Frostblitz.*", "Ruhe. Selbst die Luft hält jetzt den Atem an.", "*zieht einen Reif aus Eiskristallen durch die Luft.*", "Kälte belohnt jene, die Geduld haben.", "*lässt eine Schneeflocke auf der Hand wachsen.*", "Der Winter braucht keine Einladung.", "*zieht einen scharfen Eissplitter aus der feuchten Luft.*" } },
    ARCANE_MISSILES = { name = "Arkane Geschosse", ziel = { "Arkane Kräfte finden Euch, %s.", "*wirkt Arkane Geschosse auf %s.*", "%s, fünf Gedanken, ein einziges Ziel." }, gruppe = { "Arkane Kräfte finden Euch.", "*konzentriert sich und entfesselt Arkane Geschosse.*", "Die Gleichung ist elegant. Die Folgen weniger.", "*ordnet schwebende Glyphen in einer exakten Reihe.*", "Magie ist Mathematik mit schlechterer Fehlerbehandlung.", "*spannt einen Faden aus violettem Licht.*", "Eine Rune für jeden Fehler in Eurer Verteidigung.", "*entlässt mehrere violette Lichtpfeile aus einer schwebenden Glyphe.*", "Die Geschosse finden ihren Weg durch jede Unordnung.", "*teilt einen violetten Lichtfaden in mehrere zielsuchende Funken.*" } },
    FIRE_BLAST = { name = "Feuerschlag", ziel = { "Ein Funke genügt, %s!", "*wirkt Feuerschlag auf %s.*", "%s, dafür brauche ich keinen langen Vortrag." }, gruppe = { "Ein Funke genügt!", "*konzentriert sich und entfesselt Feuerschlag.*", "Flammen sind ehrlicher als viele Verhandlungen.", "*entfacht eine Spirale bernsteinfarbener Funken.*", "Ich hoffe, Ihr mögt es knusprig.", "*zeichnet ein glühendes Siegel in die Luft.*", "Ein Augenblick genügt, wenn die Flamme richtig sitzt.", "*schnippt und lässt die Luft mit einem trockenen Knall aufflammen.*" } },
    PYROBLAST = { name = "Pyroschlag", ziel = { "Zeit für ein richtiges Feuerwerk, %s!", "*wirkt Pyroschlag auf %s.*", "%s, diese Formel verdient etwas Abstand." }, gruppe = { "Zeit für ein richtiges Feuerwerk!", "*konzentriert sich und entfesselt Pyroschlag.*", "Flammen sind ehrlicher als viele Verhandlungen.", "*entfacht eine Spirale bernsteinfarbener Funken.*", "Ich hoffe, Ihr mögt es knusprig.", "*zeichnet ein glühendes Siegel in die Luft.*", "Dafür brauche ich einen Augenblick. Ihr dafür eine neue Frisur.", "*sammelt mit sichtlicher Mühe eine gewaltige Flamme.*", "Große Flammen erfordern eine ruhige Hand.", "*zieht einen ausgedehnten Feuerkreis und verdichtet ihn zu einer lodernden Kugel.*" } },
    FLAMESTRIKE = { name = "Flammenstoß", ziel = { "Der Boden selbst wird brennen!", "*wirkt Flammenstoß auf %s.*", "%s, achtet lieber darauf, wo Ihr steht." }, gruppe = { "Der Boden selbst wird brennen!", "*konzentriert sich und entfesselt Flammenstoß.*", "Flammen sind ehrlicher als viele Verhandlungen.", "*entfacht eine Spirale bernsteinfarbener Funken.*", "Ich hoffe, Ihr mögt es knusprig.", "*zeichnet ein glühendes Siegel in die Luft.*", "Der Boden erinnert sich an jedes falsch gesetzte Siegel.", "*zeichnet ein glühendes Muster unter den Füßen der Gegner.*" } },
    SCORCH = { name = "Versengen", ziel = { "Nur ein kleiner Vorgeschmack, %s.", "*wirkt Versengen auf %s.*", "%s, eine kleine Lektion in angewandter Hitze." }, gruppe = { "Nur ein kleiner Vorgeschmack.", "*konzentriert sich und entfesselt Versengen.*", "Flammen sind ehrlicher als viele Verhandlungen.", "*entfacht eine Spirale bernsteinfarbener Funken.*", "Ich hoffe, Ihr mögt es knusprig.", "*zeichnet ein glühendes Siegel in die Luft.*", "Nicht jede Flamme muss ein Inferno werden.", "*streicht zwei Finger durch die Luft und hinterlässt eine schmale Glutspur.*" } },
    BLIZZARD = { name = "Blizzard", ziel = { "Der Winter kennt keine Gnade!", "*wirkt Blizzard auf %s.*", "%s, sucht Euch besser einen warmen Unterschlupf." }, gruppe = { "Der Winter kennt keine Gnade!", "*konzentriert sich und entfesselt Blizzard.*", "Ruhe. Selbst die Luft hält jetzt den Atem an.", "*zieht einen Reif aus Eiskristallen durch die Luft.*", "Kälte belohnt jene, die Geduld haben.", "*lässt eine Schneeflocke auf der Hand wachsen.*", "Der Wetterbericht hat sich soeben verschlechtert.", "*ruft ein Wirbeln aus Schnee und scharfkantigem Eis herbei.*", "Wenn der Himmel schweigt, spricht der Schnee.", "*hebt beide Arme und ruft einen Wirbel aus Schnee und scharfem Eis herab.*" } },
    FROST_NOVA = { name = "Frostnova", ziel = { "Keinen Schritt weiter, %s!", "*wirkt Frostnova auf %s.*", "%s, hier endet Euer Anlauf." }, gruppe = { "Keinen Schritt weiter!", "*konzentriert sich und entfesselt Frostnova.*", "Ruhe. Selbst die Luft hält jetzt den Atem an.", "*zieht einen Reif aus Eiskristallen durch die Luft.*", "Kälte belohnt jene, die Geduld haben.", "*lässt eine Schneeflocke auf der Hand wachsen.*", "Ihr bleibt genau hier. Die Kälte besteht darauf.", "*lässt eisige Ranken über den Boden kriechen.*", "Die Kälte zeichnet eine Grenze, die niemand übersehen kann.", "*stößt die Handfläche zum Boden und lässt Frost in alle Richtungen springen.*" } },
    CONE_OF_COLD = { name = "Kältekegel", ziel = { "Ein Hauch des Nordens!", "*wirkt Kältekegel auf %s.*", "%s, die Winterluft kommt Euch entgegen." }, gruppe = { "Ein Hauch des Nordens!", "*konzentriert sich und entfesselt Kältekegel.*", "Ruhe. Selbst die Luft hält jetzt den Atem an.", "*zieht einen Reif aus Eiskristallen durch die Luft.*", "Kälte belohnt jene, die Geduld haben.", "*lässt eine Schneeflocke auf der Hand wachsen.*", "Ein Atemzug genügt, um die Nähe ungemütlich zu machen.", "*fächert die Finger auf und treibt einen eisigen Luftkeil vor sich her.*" } },
    ICE_BARRIER = { name = "Eisbarriere", ziel = {  }, gruppe = { "Kälte ist mein Schild.", "*konzentriert sich und entfesselt Eisbarriere.*", "Vorsicht ist eine Kunst, keine Schwäche.", "*zieht einen leuchtenden Kreis um die Schultern.*", "Besser geschützt als überrascht.", "*prüft die Kanten eines schimmernden Schutzzaubers.*", "Mein Schutzschild ist aus Geduld und Frost gewoben.", "*legt Schicht um Schicht hauchdünner Eiskristalle um die eigene Gestalt.*" } },
    ICE_BLOCK = { name = "Eisblock", ziel = {  }, gruppe = { "Ich bin kurz nicht zu sprechen.", "*konzentriert sich und entfesselt Eisblock.*", "Vorsicht ist eine Kunst, keine Schwäche.", "*zieht einen leuchtenden Kreis um die Schultern.*", "Besser geschützt als überrascht.", "*prüft die Kanten eines schimmernden Schutzzaubers.*", "Bitte nicht stören. Ich bin gerade tiefgekühlt.", "*schließt sich in kristallklarem Eis ein.*", "Manche Angriffe verdienen keine Antwort, nur eine Pause.", "*schließt die Augen, während klares Eis den Körper umschließt.*" } },
    ARCANE_EXPLOSION = { name = "Arkane Explosion", ziel = { "Abstand halten, die Magie wird unruhig!", "*wirkt Arkane Explosion auf %s.*", "%s, tretet aus meinem Zauberkreis." }, gruppe = { "Abstand halten, die Magie wird unruhig!", "*konzentriert sich und entfesselt Arkane Explosion.*", "Die Gleichung ist elegant. Die Folgen weniger.", "*ordnet schwebende Glyphen in einer exakten Reihe.*", "Magie ist Mathematik mit schlechterer Fehlerbehandlung.", "*spannt einen Faden aus violettem Licht.*", "Abstand ist manchmal die vernünftigste arkanische Disziplin.", "*reißt die Arme auseinander und entlädt einen Ring aus violetter Energie.*" } },
    COUNTERSPELL = { name = "Gegenzauber", ziel = { "Eure Worte enden hier, %s!", "*wirkt Gegenzauber auf %s.*", "%s, Eure Silben sind falsch gesetzt." }, gruppe = { "Eure Worte enden hier!", "*konzentriert sich und entfesselt Gegenzauber.*", "Die Gleichung ist elegant. Die Folgen weniger.", "*ordnet schwebende Glyphen in einer exakten Reihe.*", "Magie ist Mathematik mit schlechterer Fehlerbehandlung.", "*spannt einen Faden aus violettem Licht.*", "Ein schöner Zauber. Schade um die letzte Silbe.", "*zerreißt die fremde Formel mit einer knappen Handbewegung.*", "Ein Zauber kann an einer einzigen gestohlenen Silbe zerbrechen.", "*schneidet mit zwei Fingern eine fremde Formel mitten entzwei.*" } },
    POLYMORPH = { name = "Verwandlung", ziel = { "Ein wenig Wolle steht Euch gut, %s.", "*wirkt Verwandlung auf %s.*", "%s, Ihr habt eben noch deutlich größer gewirkt." }, gruppe = { "Ein wenig Wolle steht Euch gut.", "*konzentriert sich und entfesselt Verwandlung.*", "Ein wenig Wolle würde Euch gut stehen.", "*überlegt kurz, ob Hörner besser wären.*", "Keine Sorge. Das ist meistens reversibel.", "*skizziert die Umrisse eines Schafes.*", "Ich verspreche, die Verwandlung steht Euch ausgezeichnet.", "*mustert sein Gegenüber wie ein Schneider mit sehr viel Fantasie.*", "Ein wenig Demut, vier Hufe und sehr viel Wolle.", "*formt aus Licht die Umrisse eines Schafs und lässt sie über dem Ziel zusammenfallen.*" } },
    BLINK = { name = "Blinzeln", ziel = {  }, gruppe = { "Einen Augenblick, ich bin gleich woanders.", "*konzentriert sich und entfesselt Blinzeln.*", "Der kürzeste Weg ist gelegentlich sehr indirekt.", "*faltet eine Landkarte zu einem glühenden Punkt.*", "Falls ich verschwinde, waren es die Koordinaten.", "*prüft die Sterne und schließt die Augen.*", "Ihr schaut in die falsche Richtung.", "*verschwindet in einem kurzen Flimmern der Luft.*", "Der kürzeste Weg ist nicht immer der sichtbare.", "*verschwindet in einem schmalen blauen Lichtspalt und taucht einen Herzschlag später wieder auf.*" } },
    SLOW_FALL = { name = "Langsamer Fall", ziel = { "Die Schwerkraft kann heute warten.", "*wirkt Langsamer Fall auf %s.*" }, gruppe = { "Die Schwerkraft kann heute warten.", "*konzentriert sich und entfesselt Langsamer Fall.*", "Der kürzeste Weg ist gelegentlich sehr indirekt.", "*faltet eine Landkarte zu einem glühenden Punkt.*", "Falls ich verschwinde, waren es die Koordinaten.", "*prüft die Sterne und schließt die Augen.*", "Die Schwerkraft wird heute eine Ausnahme machen.", "*zeichnet einen federleichten Bogen unter die Stiefel.*" } },
    EVOCATION = { name = "Hervorrufung", ziel = {  }, gruppe = { "Einen Moment, ich sammle meine Gedanken und mein Mana.", "*konzentriert sich und entfesselt Hervorrufung.*", "Die Gleichung ist elegant. Die Folgen weniger.", "*ordnet schwebende Glyphen in einer exakten Reihe.*", "Magie ist Mathematik mit schlechterer Fehlerbehandlung.", "*spannt einen Faden aus violettem Licht.*", "Geduld. Meine Reserven sind nicht unerschöpflich.", "*zieht langsam arkane Ströme aus der Umgebung.*", "Selbst große Kunst braucht gelegentlich eine Atempause.", "*zieht verstreute Manafunken langsam in die Handflächen zurück.*" } },
    ARCANE_INTELLECT = { name = "Arkane Intelligenz", ziel = { "Ein klarer Geist ist die beste Waffe, %s.", "*wirkt Arkane Intelligenz auf %s.*", "%s, möge Euer Verstand klarer sein als Euer Schwert." }, gruppe = { "Ein klarer Geist ist die beste Waffe.", "*konzentriert sich und entfesselt Arkane Intelligenz.*", "Ein klarer Geist wirkt Wunder, ganz ohne Wunder.", "*legt zwei Finger an die Stirn.*", "Wissen ist der angenehmste aller Vorteile.", "*überträgt eine sanft leuchtende Glyphe.*", "Ein geschärfter Verstand wiegt mehr als ein ganzer Waffenschrank.", "*setzt eine leuchtende Rune behutsam auf die Stirn.*", "Ein wacher Geist ist der verlässlichste Talisman.", "*setzt eine kleine leuchtende Glyphe an die Schläfe.*" } },
    ARCANE_BRILLIANCE = { name = "Arkane Brillanz", ziel = { "Mögen unsere Gedanken heller leuchten!", "*wirkt Arkane Brillanz auf %s.*", "%s, Wissen wird besser, wenn man es teilt." }, gruppe = { "Mögen unsere Gedanken heller leuchten!", "*konzentriert sich und entfesselt Arkane Brillanz.*", "Ein klarer Geist wirkt Wunder, ganz ohne Wunder.", "*legt zwei Finger an die Stirn.*", "Wissen ist der angenehmste aller Vorteile.", "*überträgt eine sanft leuchtende Glyphe.*", "Die klügste Gruppe ist jene, die gemeinsam denkt.", "*breitet ein Netz heller Runen über die Verbündeten aus.*" } },
    MANA_SHIELD = { name = "Manaschild", ziel = {  }, gruppe = { "Mana zu Schutz, Gedanken zu Stahl.", "*konzentriert sich und entfesselt Manaschild.*", "Vorsicht ist eine Kunst, keine Schwäche.", "*zieht einen leuchtenden Kreis um die Schultern.*", "Besser geschützt als überrascht.", "*prüft die Kanten eines schimmernden Schutzzaubers.*", "Meine Gedanken sind schwerer zu durchdringen als meine Robe.", "*wickelt fließende Manafäden schützend um die Schultern.*" } },
    CONJURE_FOOD = { name = "Essen herbeizaubern", ziel = {  }, gruppe = { "Ein bisschen Magie gegen den Hunger.", "*konzentriert sich und entfesselt Essen herbeizaubern.*", "Etwas Essbares ist auch eine Form hoher Magie.", "*schüttelt ein paar Funken aus dem Ärmel.*", "Hoffentlich ist die Rezeptur diesmal nicht zu süß.", "*prüft das frisch herbeigezauberte Ergebnis.*", "Ein bisschen Brot hat schon manch heldenhafte Reise gerettet.", "*zaubert mit einer Verbeugung einen kleinen Imbiss hervor.*", "Gute Magie stillt gelegentlich auch den Hunger.", "*öffnet die Hände und lässt einen frisch duftenden Imbiss erscheinen.*" } },
    CONJURE_WATER = { name = "Wasser herbeizaubern", ziel = {  }, gruppe = { "Frisches Wasser aus reiner Magie.", "*konzentriert sich und entfesselt Wasser herbeizaubern.*", "Etwas Essbares ist auch eine Form hoher Magie.", "*schüttelt ein paar Funken aus dem Ärmel.*", "Hoffentlich ist die Rezeptur diesmal nicht zu süß.", "*prüft das frisch herbeigezauberte Ergebnis.*", "Wasser ist die vernünftigste aller Beschwörungen.", "*lässt perlende Tropfen zu einer Karaffe verschmelzen.*", "Trinkt. Die arkanen Studien sind ein durstiges Geschäft.", "*fängt einen Tropfen Licht auf und verwandelt ihn in klares Wasser.*" } },
    CREATE_MANA_GEM = { name = "Manastein erschaffen", ziel = {  }, gruppe = { "Ein kleiner Vorrat für große Not.", "*konzentriert sich und entfesselt Manastein erschaffen.*", "Etwas Essbares ist auch eine Form hoher Magie.", "*schüttelt ein paar Funken aus dem Ärmel.*", "Hoffentlich ist die Rezeptur diesmal nicht zu süß.", "*prüft das frisch herbeigezauberte Ergebnis.*", "Eine kleine Reserve für ein großes Problem.", "*presst flackerndes Mana zu einem kühlen, leuchtenden Edelstein.*" } },
    PORTAL = { name = "Portal", ziel = {  }, gruppe = { "Bitte beim Durchgang keine Gliedmaßen verlieren.", "*konzentriert sich und entfesselt Portal.*", "Bitte die Gliedmaßen innerhalb des Portals behalten.", "*prüft zweimal die Zielkoordinaten.*", "Reisekosten: etwas Mana und volles Vertrauen.", "*öffnet einen schimmernden Durchgang.*", "Wer zuerst hindurchgeht, darf mir anschließend berichten.", "*prüft misstrauisch die Farbe des Portalrandes.*", "Wer hindurchgeht, sollte dem Zielkreis vertrauen.", "*öffnet vorsichtig eine runde Falte im Gewebe des Raumes.*" } },
    TELEPORT = { name = "Teleportieren", ziel = {  }, gruppe = { "Ich nehme die Abkürzung durch das Raumgefüge.", "*konzentriert sich und entfesselt Teleportieren.*", "Der kürzeste Weg ist gelegentlich sehr indirekt.", "*faltet eine Landkarte zu einem glühenden Punkt.*", "Falls ich verschwinde, waren es die Koordinaten.", "*prüft die Sterne und schließt die Augen.*", "Ein Schritt, ein Koordinatenfehler, tausend Meilen Unterschied.", "*zeichnet die Zielrune und löst sich in einen Wirbel aus Licht auf.*" } },
    REMOVE_LESSER_CURSE = { name = "Geringen Fluch aufheben", ziel = { "Der Fluch hat hier nichts verloren, %s.", "*wirkt Geringen Fluch aufheben auf %s.*", "%s, dieser Fluch hat sich lange genug festgekrallt." }, gruppe = { "Der Fluch hat hier nichts verloren.", "*konzentriert sich und entfesselt Geringen Fluch aufheben.*", "Es gibt für alles eine Formel. Meistens.", "*schlägt die passende Seite seines Zauberbuchs auf.*", "Magie hilft auch bei kleinen Schwierigkeiten.", "*zeichnet ein unscheinbares Symbol.*", "Kein Bann hält ewig, wenn man seine Knoten kennt.", "*löst mit einer leuchtenden Rune den Schatten von einer Schulter.*" } },
    DETECT_MAGIC = { name = "Magie entdecken", ziel = { "Mal sehen, welche Geheimnisse Ihr tragt, %s.", "*wirkt Magie entdecken auf %s.*", "%s, Eure Aura verrät mehr als Eure Worte." }, gruppe = { "Mal sehen, welche Geheimnisse Ihr tragt.", "*konzentriert sich und entfesselt Magie entdecken.*", "Es gibt für alles eine Formel. Meistens.", "*schlägt die passende Seite seines Zauberbuchs auf.*", "Magie hilft auch bei kleinen Schwierigkeiten.", "*zeichnet ein unscheinbares Symbol.*", "Verborgene Ströme hinterlassen immer eine Spur.", "*hält ein schimmerndes Zeichen ins Licht und betrachtet die Antwort.*" } },
    DAMPEN_MAGIC = { name = "Magie dämpfen", ziel = { "Magische Strömungen werden leiser. %s", "%s, ein wenig weniger Zauberlärm wird Euch guttun.", "Nicht jede Macht muss mit voller Stimme sprechen.", "*legt einen silbrigen Schleier über die pulsierenden Manaströme.*" }, gruppe = { "Magische Strömungen werden leiser.", "Ein klarer Geist wirkt Wunder, ganz ohne Wunder.", "*legt zwei Finger an die Stirn.*", "Wissen ist der angenehmste aller Vorteile.", "*überträgt eine sanft leuchtende Glyphe.*", "Nicht jede Macht muss mit voller Stimme sprechen.", "*legt einen silbrigen Schleier über die pulsierenden Manaströme.*" } },
    AMPLIFY_MAGIC = { name = "Magie verstärken", ziel = { "Mehr Magie, mehr Möglichkeiten. %s", "%s, ich öffne Eure Sinne für stärkere Ströme.", "Mehr Kraft ist nur dann ein Geschenk, wenn man sie führen kann.", "*weitet mit einer langsamen Geste den leuchtenden Kreis um den Verbündeten.*" }, gruppe = { "Mehr Magie, mehr Möglichkeiten.", "Ein klarer Geist wirkt Wunder, ganz ohne Wunder.", "*legt zwei Finger an die Stirn.*", "Wissen ist der angenehmste aller Vorteile.", "*überträgt eine sanft leuchtende Glyphe.*", "Mehr Kraft ist nur dann ein Geschenk, wenn man sie führen kann.", "*weitet mit einer langsamen Geste den leuchtenden Kreis um den Verbündeten.*" } },
    FROST_ARMOR = { name = "Frostrüstung", ziel = {  }, gruppe = { "Ein frostiger Mantel steht mir gut.", "Vorsicht ist eine Kunst, keine Schwäche.", "*zieht einen leuchtenden Kreis um die Schultern.*", "Besser geschützt als überrascht.", "*prüft die Kanten eines schimmernden Schutzzaubers.*", "Ein kühler Kopf verdient eine ebenso kühle Rüstung.", "*zieht einen schimmernden Reif aus Frost um Schultern und Arme.*" } },
    ICE_ARMOR = { name = "Eisrüstung", ziel = {  }, gruppe = { "Ein Schutzpanzer aus klirrendem Eis.", "Vorsicht ist eine Kunst, keine Schwäche.", "*zieht einen leuchtenden Kreis um die Schultern.*", "Besser geschützt als überrascht.", "*prüft die Kanten eines schimmernden Schutzzaubers.*", "Wer mich berührt, soll zuerst den Winter begrüßen.", "*lässt harte Eisschuppen wie Schuppenpanzer über die Robe wachsen.*" } },
    MAGE_ARMOR = { name = "Magische Rüstung", ziel = {  }, gruppe = { "Mein Geist ist mein bester Panzer.", "Vorsicht ist eine Kunst, keine Schwäche.", "*zieht einen leuchtenden Kreis um die Schultern.*", "Besser geschützt als überrascht.", "*prüft die Kanten eines schimmernden Schutzzaubers.*", "Arkane Ordnung beginnt unmittelbar unter meiner Robe.", "*lässt eine kaum sichtbare Schicht schützender Glyphen aufleuchten.*" } },
    FIRE_WARD = { name = "Feuerzauberschutz", ziel = {  }, gruppe = { "Feuer soll mich nicht verzehren.", "Vorsicht ist eine Kunst, keine Schwäche.", "*zieht einen leuchtenden Kreis um die Schultern.*", "Besser geschützt als überrascht.", "*prüft die Kanten eines schimmernden Schutzzaubers.*", "Feuer erkennt Feuer, aber nicht jedes Feuer darf passieren.", "*schließt einen goldenen Feuerring zu einem schützenden Siegel.*" } },
    FROST_WARD = { name = "Frostzauberschutz", ziel = {  }, gruppe = { "Die Kälte gehorcht mir.", "Vorsicht ist eine Kunst, keine Schwäche.", "*zieht einen leuchtenden Kreis um die Schultern.*", "Besser geschützt als überrascht.", "*prüft die Kanten eines schimmernden Schutzzaubers.*", "Der Winter klopft an. Meine Antwort steht bereits fest.", "*spannt einen transparenten Kristallkreis gegen die eisige Luft.*" } },
    ARCANE_BLAST = { name = "Arkanbeschuss", ziel = { "Arkane Energie bricht hervor! %s", "%s, diese Energie lässt sich nicht wegdiskutieren.", "Reine Macht braucht keine Flammen, um Spuren zu hinterlassen.", "*stößt eine dichte Welle aus violettem Licht nach vorn.*" }, gruppe = { "Arkane Energie bricht hervor!", "Die Gleichung ist elegant. Die Folgen weniger.", "*ordnet schwebende Glyphen in einer exakten Reihe.*", "Magie ist Mathematik mit schlechterer Fehlerbehandlung.", "*spannt einen Faden aus violettem Licht.*", "Reine Macht braucht keine Flammen, um Spuren zu hinterlassen.", "*stößt eine dichte Welle aus violettem Licht nach vorn.*" } },
    ARCANE_WRATH = { name = "Arkaner Zorn", ziel = { "Die arkanen Ströme antworten auf meinen Zorn. %s", "%s, meine Geduld war die letzte Schutzschicht.", "Die Arkanen antworten auf Unvernunft mit Nachdruck.", "*verdreht zwei schwebende Siegel, bis ein greller Lichtstoß daraus hervorbricht.*" }, gruppe = { "Die arkanen Ströme antworten auf meinen Zorn.", "Die Gleichung ist elegant. Die Folgen weniger.", "*ordnet schwebende Glyphen in einer exakten Reihe.*", "Magie ist Mathematik mit schlechterer Fehlerbehandlung.", "*spannt einen Faden aus violettem Licht.*", "Die Arkanen antworten auf Unvernunft mit Nachdruck.", "*verdreht zwei schwebende Siegel, bis ein greller Lichtstoß daraus hervorbricht.*" } },
    ARCANE_POWER = { name = "Arkane Macht", ziel = {  }, gruppe = { "Mehr Macht, doch zu welchem Preis?", "Die Gleichung ist elegant. Die Folgen weniger.", "*ordnet schwebende Glyphen in einer exakten Reihe.*", "Magie ist Mathematik mit schlechterer Fehlerbehandlung.", "*spannt einen Faden aus violettem Licht.*", "Jetzt darf die Theorie zeigen, was sie wirklich wert ist.", "*öffnet die Hände und lässt grelle Runenkreise schneller umeinander rotieren.*" } },
    PRESENCE_OF_MIND = { name = "Geistesgegenwart", ziel = {  }, gruppe = { "Ein Gedanke genügt.", "Die Gleichung ist elegant. Die Folgen weniger.", "*ordnet schwebende Glyphen in einer exakten Reihe.*", "Magie ist Mathematik mit schlechterer Fehlerbehandlung.", "*spannt einen Faden aus violettem Licht.*", "Manche Gedanken sind schneller als die Zunge.", "*hält kurz inne, als würden alle denkbaren Wege gleichzeitig sichtbar.*" } },
    BLAST_WAVE = { name = "Druckwelle", ziel = { "Ein Sturm aus Feuer und Wucht! %s", "%s, Ihr steht zu nah an meinem Mittelpunkt.", "Wenn die Luft zurückschlägt, ist Abstand keine schlechte Idee.", "*schlägt mit den Handflächen zusammen und treibt eine glühende Druckwelle fort.*" }, gruppe = { "Ein Sturm aus Feuer und Wucht!", "Flammen sind ehrlicher als viele Verhandlungen.", "*entfacht eine Spirale bernsteinfarbener Funken.*", "Ich hoffe, Ihr mögt es knusprig.", "*zeichnet ein glühendes Siegel in die Luft.*", "Wenn die Luft zurückschlägt, ist Abstand keine schlechte Idee.", "*schlägt mit den Handflächen zusammen und treibt eine glühende Druckwelle fort.*" } },
