    POLYMORPH_COW = { name = "Verwandlung: Kuh", ziel = { "Ein Muh ist auch eine Antwort. %s", "%s, ich hoffe, Ihr habt nichts gegen Kuhglocken.", "Heute gibt es vier Beine und reichlich Gras.", "*zeichnet die Umrisse einer Kuh aus sanft schimmernden Runen.*" }, gruppe = { "Ein Muh ist auch eine Antwort.", "Ein wenig Wolle würde Euch gut stehen.", "*überlegt kurz, ob Hörner besser wären.*", "Keine Sorge. Das ist meistens reversibel.", "*skizziert die Umrisse eines Schafes.*", "Heute gibt es vier Beine und reichlich Gras.", "*zeichnet die Umrisse einer Kuh aus sanft schimmernden Runen.*" } },
